-- Datos de prueba adicionales para db_santuario (julio 2025 - octubre 2026).
-- Ejecutar DESPUÉS de santuario_completo.sql, sobre una base recién creada.
-- Usuarios nuevos: usan las mismas claves que las cuentas demo de su rol.
-- ============================================================================
USE db_santuario;
SET NAMES utf8mb4;
START TRANSACTION;

-- El personal original ya trabajaba desde 2025 (los datos nuevos empiezan en julio de 2025)
UPDATE tbl_usuario SET fecha_registro = '2025-06-01 08:30:00' WHERE id_usuario IN (1, 2);

-- Usuarios (2 del personal y padrinos con cuenta)





-- Stock de los medicamentos originales tras los consumos generados
UPDATE tbl_medicamento SET stock_actual = 36.00 WHERE id_medicamento = 1;
UPDATE tbl_medicamento SET stock_actual = 288.00 WHERE id_medicamento = 2;
UPDATE tbl_medicamento SET stock_actual = 171.00 WHERE id_medicamento = 3;







-- Período de los aportes originales (la columna se agregó después de insertarlos)
UPDATE tbl_donacion SET periodo_aporte = '2026-10-01' WHERE id_donacion = 1;
UPDATE tbl_donacion SET periodo_aporte = '2026-09-01' WHERE id_donacion = 2;


COMMIT;

-- Resumen
SELECT 'animales' AS tabla, COUNT(*) AS filas FROM tbl_animal UNION ALL SELECT 'atenciones', COUNT(*) FROM tbl_atencion_medica UNION ALL SELECT 'liberaciones', COUNT(*) FROM tbl_liberacion UNION ALL SELECT 'apadrinamientos', COUNT(*) FROM tbl_apadrinamiento UNION ALL SELECT 'donaciones', COUNT(*) FROM tbl_donacion;
